<?php
namespace App\Application\Sso;
use RuntimeException;
class SsoTokenValidator { public function __construct(private JwtService $jwt){} public function validate(string $token):array{$secret=(string)config('gpha_sso.shared_secret');if(strlen($secret)<32)throw new RuntimeException('EMS SSO signing secret must be at least 32 characters.');$claims=$this->jwt->decodeAndVerify($token,$secret);$this->claims($claims);return $claims;} private function claims(array $c):void{if(!hash_equals((string)config('gpha_sso.issuer'),(string)($c['iss']??'')))throw new RuntimeException('Invalid token issuer.');$aud=array_map('strval',(array)($c['aud']??[]));if(array_intersect($aud,config('gpha_sso.allowed_audiences'))===[])throw new RuntimeException('Invalid token audience.');$modules=[];foreach(['moduleId','module_id','ModuleId','modules'] as $key)foreach((array)($c[$key]??[]) as $v)$modules[]=trim((string)$v);if(!in_array((string)config('gpha_sso.module_id'),$modules,true))throw new RuntimeException('Token is not authorized for the EMS module.');if($this->userId($c)==='')throw new RuntimeException('Missing token user identity.');$now=time();$skew=config('gpha_sso.clock_skew_seconds');$exp=$this->timestamp($c,'exp',true);if($exp<=($now-$skew))throw new RuntimeException('Token has expired.');$nbf=$this->timestamp($c,'nbf');if($nbf!==null&&$nbf>($now+$skew))throw new RuntimeException('Token is not valid yet.');$iat=$this->timestamp($c,'iat');if($iat!==null&&$iat>($now+$skew))throw new RuntimeException('Token was issued in the future.');if($iat!==null&&($exp-$iat)>config('gpha_sso.token_ttl_minutes')*60)throw new RuntimeException('Token lifetime exceeds the configured limit.');} public function userId(array $c):string{foreach(['UserId','sub','nameid','http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier'] as $k)if(trim((string)($c[$k]??''))!=='')return trim((string)$c[$k]);return '';} private function timestamp(array $c,string $key,bool $required=false):?int{if(!array_key_exists($key,$c)){if($required)throw new RuntimeException("Missing token $key.");return null;}if(!is_numeric($c[$key]))throw new RuntimeException("Invalid token $key.");return(int)$c[$key];} }
